
.panel {
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  padding: 10px 12px;
  min-height: 140px;
}
h3 {
  font-size: 13px;
  margin-bottom: 8px;
}
ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
li {
  border-bottom: 1px dashed rgba(150, 120, 90, 0.35);
  padding-bottom: 6px;
  font-size: 12px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 8px;
}
li p {
  grid-column: 1 / -1;
  color: var(--c-text-muted);
  font-size: 11px;
}
.empty {
  color: var(--c-text-muted);
  font-size: 12px;
}
