
.topbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
  align-items: center;
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  padding: 8px 10px;
  font-size: 12px;
  font-weight: 600;
}

.item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--c-text);
}

.map-btn {
  margin-left: auto;
  border: 1px solid var(--c-border);
  background: var(--c-surface);
  border-radius: 4px;
  padding: 3px 8px;
  font-size: 12px;
  font-weight: 700;
}

.map-btn:hover {
  background: var(--c-primary);
  color: #fff;
  border-color: var(--c-primary);
}
