
.panel {
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  padding: 10px 12px;
  min-height: 140px;
}
h3 {
  font-size: 13px;
  margin-bottom: 8px;
}
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
}
.card {
  background: #fff;
  border: 1px solid var(--c-border);
  padding: 8px;
  box-shadow: var(--shadow-paper);
}
header {
  display: flex;
  justify-content: space-between;
  gap: 6px;
  font-size: 12px;
  margin-bottom: 4px;
}
.heart {
  color: var(--c-heart);
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 4px;
}
.meta {
  font-size: 11px;
  color: var(--c-text-muted);
}
.promises {
  margin-top: 4px;
  padding-left: 14px;
  font-size: 11px;
}
.empty {
  color: var(--c-text-muted);
  font-size: 12px;
}
