
.id-card {
  background: var(--c-surface-id);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  overflow: hidden;
}

header {
  background: #4a6f95;
  color: #f4f8fc;
  padding: 6px 10px;
  display: flex;
  justify-content: space-between;
  font-weight: 700;
  font-size: 12px;
}

.body {
  padding: 10px;
}

.name-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
}

.bio {
  font-size: 12px;
  color: var(--c-text-muted);
  margin-bottom: 8px;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.bar {
  display: grid;
  grid-template-columns: 32px 1fr 36px;
  gap: 6px;
  align-items: center;
  font-size: 11px;
}

.track {
  height: 7px;
  background: rgba(255, 255, 255, 0.7);
  border: 1px solid var(--c-border);
  border-radius: 999px;
  overflow: hidden;
}

.track i {
  display: block;
  height: 100%;
}

.money {
  margin-top: 8px;
  font-weight: 700;
  font-size: 12px;
}
