
.map-panel {
  background: var(--c-surface-folder);
  border: 1px solid var(--c-border);
  box-shadow: var(--shadow-paper);
  padding: 8px;
}

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 8px;
}

.tab {
  border: 1px solid var(--c-border);
  background: var(--c-surface-paper);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 700;
}

.tab.on {
  background: var(--c-primary);
  color: #fff;
  border-color: var(--c-primary);
}

.map {
  position: relative;
  min-height: 280px;
  background: #d9c7a8 center / cover no-repeat;
  border-radius: 4px;
  overflow: hidden;
}

.pin {
  position: absolute;
  transform: translate(-50%, -100%);
  background: transparent;
  border: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.head {
  width: 14px;
  height: 14px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  background: #c45c4a;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
}

.label {
  background: rgba(255, 250, 240, 0.95);
  border: 1px solid var(--c-border);
  padding: 1px 5px;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.hint,
.empty {
  margin-top: 6px;
  font-size: 11px;
  color: var(--c-text-muted);
  text-align: center;
}

.list-stage ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.list-stage li {
  display: flex;
  gap: 10px;
  align-items: center;
  background: var(--c-surface-paper);
  border: 1px solid var(--c-border);
  padding: 6px 8px;
  font-size: 12px;
}

.list-stage button {
  border: 1px solid var(--c-primary);
  background: #fff;
  color: var(--c-primary);
  border-radius: 4px;
  padding: 3px 8px;
  font-weight: 700;
}
